        for (char c = '0'; c <= '9'; c++) {
            digit_map.put(c, c - '0');
        }
        for (char c = 'a'; c <= 'z'; c++) {
            digit_map.put(c, c - 'a' + 10);
        }
        for (char c = 'A'; c <= 'Z'; c++) {
            digit_map.put(c, c - 'A' + 10);
        }
    }

