public static int digitValue(char c) {
    if (!Character.isDigit(c)) {
       return -1;
    }

    if (c <= '9') {
      return c - '0';
    }

    if (c >= 'a' && c <= 'z') {
      return c - 'a' + 10;
    }

    if (c >= 'A' && c <= 'Z') {
      return c - 'A' + 10;
    }

    return -1;
  }

public static int parseInt(String s) throws NumberFormatException {
    int len = s.length();
    if (len == 0) {
      throw new NumberFormatException("Empty string");
    }

    int signum = 1;
    if (s.charAt(0) == '-') {
      if (len == 1) {
        throw new NumberFormatException("Sign character not followed by a digit");
      }
      signum = -1;
    }

    int result = 0;
    for (int i = len - 1; i >= 0; i--) {
      int digit = digitValue(s.charAt(i));
      if (digit < 0) {
        throw new NumberFormatException("Unrecognized digit: " + s.charAt(i));
      }
      result = result * 10 + digit;
    }

    return result * signum;
  }

