protected int removeUnusedNodes() {
    // Step 1: Identify the unused nodes
    List<TreeNode> unusedNodes = new ArrayList<>();
    for (TreeNode node : getRoot().getChildren()) {
        if (!node.isActive()) {
            unusedNodes.add(node);
        }
    }

    // Step 2: Remove the unused nodes
    for (TreeNode node : unusedNodes) {
        getRoot().remove(node);
    }

    // Step 3: Return the number of removed nodes
    return unusedNodes.size();
}

