        String obj1 = (String) aObj1;
        String obj2 = (String) aObj2;
        return obj1.compareTo(obj2);
    } else if (aObj1 instanceof Integer && aObj2 instanceof Integer) {
        int obj1 = (int) aObj1;
        int obj2 = (int) aObj2;
        return obj1 - obj2;
    } else if (aObj1 instanceof Double && aObj2 instanceof Double) {
        double obj1 = (double) aObj1;
        double obj2 = (double) aObj2;
        return Double.compare(obj1, obj2);
    } else {
        throw new IllegalArgumentException("Cannot compare objects of different types");
    }
}

