protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    // Create a new graph path
    GraphPath<V, E> path = new GraphPath<V, E>(graph);

    // Iterate over the edges in the tour set
    for (E edge : tour) {
        // Add the source and target vertices to the path
        path.addVertex(edge.getSource());
        path.addVertex(edge.getTarget());

        // Add the edge to the path
        path.addEdge(edge);
    }

    return path;
}

GraphPath<V,E> function (Set<E> tour, Graph<V,E> graph) {
    // Create an empty graph path with the same vertex and edge types as the graph
    GraphPath<V,E> newTour = graph.createEmptyPath();

    // Iterate over the edges in the tour set
    for (E edge : tour) {
        // Add the edge to the graph path
        newTour.addEdge(edge);
    }

    // Return the new graph path
    return newTour;
}

