private synchronized void _putProperty(final int index, final StringBuilder desc) {
// throws IndexOutOfBoundsException if index is invalid
desc.insert(0, planCode(index));
}

private StringBuilder planCode(final int index) {
// throws IndexOutOfBoundsException if index is invalid
StringBuilder plan = new StringBuilder();
switch(types[index]) {
    case FIELD:
    case METHOD_HANDLE:
    case METHOD_TYPE:
        plan.append('L');
        break;
    case INTEGER:
        plan.append('I');
        break;
    case FLOAT:
        plan.append('F');
        break;
    case LONG:
        plan.append('J');
        break;
    case DOUBLE:
        plan.append('D');
        break;
    case BYTE:
        plan.append('B');
        break;
    case CHAR:
        plan.append('C');
        break;
    case SHORT:
        plan.append('S');
        break;
    case BOOLEAN:
        plan.append('Z');
        break;
    case STRING:
        plan.append('T');
        break;
    case UTF8:
        plan.append('U');
        break;
    default:
        throw new RuntimeException("Invalid input: " + descriptor);
}}

