if (!bucketsByLabel.get(0).contains(vertex)) {
bucketsByLabel.get(0).add(vertex);
}
});
bucketsByLabel.get(i).clear();
labels.set(i, 0);
}
}
}

void function (List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {

    // Move all vertices from the bucket with label minLabel to the bucket with label 0
    for (Set<Integer> vertices : bucketsByLabel.get(minLabel)) {
        for (int vertex : vertices) {
            bucketsByLabel.get(0).add(vertex);
        }
    }

    // Clear the bucket with label minLabel
    bucketsByLabel.get(0).removeAll(bucketsByLabel.get(minLabel));

    // Update the labeling accordingly
    labels.set(minLabel, 0);
}

