    List<Integer> suffixSum = new ArrayList<>();
    long sum = 0;
    for (int i = bounds.size() - 1; i >= 0; i--) {
        sum += bounds.get(i);
        suffixSum.add(sum);
    }
    return new Pair<>(suffixSum, sum);
}

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    // Initialize empty list to store the computed suffix sum
    List<Integer> suffixSumList = new ArrayList<>();

    // Initialize a long variable to store the sum of all elements in the list
    long sumOfAllElements = 0L;

    // Iterate over the list of bounds
    for (Integer bound : bounds) {
        // Compute the suffix sum for the current bound
        long suffixSum = 0L;
        for (int i = 0; i < bound; i++) {
            suffixSum += i;
        }

        // Add the computed suffix sum to the list
        suffixSumList.add((int) suffixSum);

        // Add the sum of the elements in the current bound to the sum of all elements
        sumOfAllElements += suffixSum;
    }

    // Return a pair of the computed suffix sum list and the sum of all elements
    return Pair.of(suffixSumList, sumOfAllElements);
}

