public void abbreviate(int nameStart, StringBuffer buf) {
	// Check if nameStart is valid
	if (nameStart < 0 || nameStart >= buf.length()) {
		throw new IllegalArgumentException("Invalid name start index");
	}

	// Get the first letter of the name
	char firstLetter = buf.charAt(nameStart);

	// Check if the first letter is a valid letter
	if (!Character.isLetter(firstLetter)) {
		throw new IllegalArgumentException("First letter is not a letter");
	}

	// Get the length of the name
	int nameLength = buf.length() - nameStart;

	// Check if the name is too long
	if (nameLength > 10) {
