public static String applyRelativePath(String path, String relativePath) {
    if (relativePath.startsWith(File.separator)) {
        return relativePath;
    }
    String[] pathComponents = path.split(File.separator);
    String[] relativePathComponents = relativePath.split(File.separator);
    String result = "";
    for (int i = 0; i < relativePathComponents.length; i++) {
        if (relativePathComponents[i].equals("..")) {
            if (pathComponents.length > 1) {
                pathComponents = Arrays.copyOfRange(pathComponents, 0, pathComponents.length - 1);
            }
        } else {
            result += relativePathComponents[i] + File.separator;
        }
    }
    result = result.substring(0, result.length() - 1);
    return result;
}

