public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {

List<ThreadSnapshot> threadSnapshots = new ArrayList<ThreadSnapshot>();

// Open the file for reading
try (FileInputStream fis = new FileInputStream(file)) {

    // Parse the file contents
    HprofParser parser = new HprofParser(fis);

    // Iterate over the time ranges
    for (ProfileAnalyzeTimeRange timeRange : timeRanges) {

        // Parse the snapshots within the current time range
        List<ThreadSnapshot> snapshots = parser.parseSnapshots(timeRange.getTimeRangeInMillis());

        // Add the snapshots to the list
        threadSnapshots.addAll(snapshots);
    }
}

// Return the list of thread snapshots
return threadSnapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (Reader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            String[] tokens = line.split("\\s+");
            if (tokens.length >= 3) {
                long timestamp = Long.parseLong(tokens[0]);
                String threadName = tokens[1];
                String eventType = tokens[2];
                if (eventType.equals("snapshot")) {
                    threadSnapshots.add(new ThreadSnapshot(timestamp, threadName));
                } else if (eventType.equals("end")) {
                    ThreadSnapshot threadSnapshot = threadSnapshots.get(threadSnapshots.size() - 1);
                    threadSnapshot.setEndTime(timestamp);
                }
            }
        }
    }
    for (ThreadSnapshot threadSnapshot : threadSnapshots) {
        for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
            if (timeRange.contains(threadSnapshot.getStartTime(), threadSnapshot.getEndTime())) {
                threadSnapshot.addTimeRange(timeRange);
                break;
            }
        }
    }
    return threadSnapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
  List<ThreadSnapshot> result = new ArrayList<>();
  try (BufferedReader br = new BufferedReader(new FileReader(file))) {
    String line;
    while ((line = br.readLine()) != null) {
      if (line.startsWith("THREAD_SNAPSHOT")) {
        String threadName = null;
        long startTime = 0;
        long endTime = 0;
        while (!line.startsWith("END_THREAD_SNAPSHOT")) {
          if (line.startsWith("THREAD_NAME")) {
            threadName = line.substring("THREAD_NAME ".length());
          } else if (line.startsWith("START_TIME")) {
            startTime = Long.parseLong(line.substring("START_TIME ".length()));
          } else if (line.startsWith("END_TIME")) {
            endTime = Long.parseLong(line.substring("END_TIME ".length()));
          }
          line = br.readLine();
        }
        if (threadName != null) {
          for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
            if (!timeRange.isWithin(startTime, endTime)) {
              continue;
            }
            result.add(new ThreadSnapshot(threadName, startTime, endTime));
          }
        }
      }
    }
  }
  return result;
}

List<ThreadSnapshot> function (File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    FileInputStream fis = new FileInputStream(file);
    BufferedInputStream bis = new BufferedInputStream(fis);
    DataInputStream dis = new DataInputStream(bis);

    // Parse header
    String magicNumber = dis.readUTF();
    if (!magicNumber.equals("MagicNumber")) {
        throw new IOException("Invalid magic number");
    }
    int version = dis.readInt();
    int snapshotCount = dis.readInt();
    List<ThreadSnapshot> snapshots = new ArrayList<>();

    // Read snapshot data
    for (int i = 0; i < snapshotCount; i++) {
        long timestamp = dis.readLong();
        int threadId = dis.readInt();
        int size = dis.readInt();
        byte[] data = new byte[size];
        dis.readFully(data);
        snapshots.add(new ThreadSnapshot(timestamp, threadId, data));
    }

    // Filter snapshots based on time range
    for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
        snapshots.removeIf(s -> s.getTimestamp() < timeRange.getStartTime() || s.getTimestamp() > timeRange.getEndTime());
    }

    return snapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> snapshots = new ArrayList<>();
    try (HprofFile hprofFile = HprofFile.open(file)) {
        for (ThreadSnapshot snapshot : hprofFile.iterateThreadSnapshots()) {
            for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
                if (snapshot.getStartMillis() >= timeRange.getStartMillis() && snapshot.getEndMillis() <= timeRange.getEndMillis()) {
                    snapshots.add(snapshot);
                }
            }
        }
    }
    return snapshots;
}
